/* Robot Script -- R4-RSMO-2: a soft tick for each step of a run and a longer buzz at the exit, through the browser's
 * vibration call where it exists (most phones; nothing happens on desktop browsers). Generated by the device, no audio
 * and no files. Off under reduced motion and when the Effects setting is off. */
(function () {
  "use strict";
  function allowed() {
    var root = document.documentElement;
    if (root.getAttribute("data-reduced-motion") === "true" || root.getAttribute("data-effects") === "off") return false;
    return typeof navigator !== "undefined" && typeof navigator.vibrate === "function";
  }
  function pulse(ms) {
    if (!allowed()) return;
    try { navigator.vibrate(ms); } catch (e) { /* the browser may refuse before a tap; it is only a nicety */ }
  }
  window.RobotHaptics = {
    tick: function () { pulse(8); },
    buzz: function () { pulse(120); }
  };
})();
